// Registering the worker is what lets a phone install the page to the home screen.
// It is deliberately quiet: if it fails, the page carries on exactly as before.
export const PWA_BOOT = `
if ('serviceWorker' in navigator) {
  window.addEventListener('load', function () {
    navigator.serviceWorker.register('/sw.js').catch(function () {});
  });
}`;

