// One <select> of projects. Owners get every project and switching reloads the page;
// everyone else sees only their own, so it renders as a plain label instead.
export const SWITCHER_JS = `
async function mountSwitcher(elId) {
  var el = document.getElementById(elId);
  if (!el) return;
  try {
    var r = await fetch('/api/projects', { cache: 'no-store' });
    if (!r.ok) return;
    var d = await r.json();
    if (!d.projects || d.projects.length === 0) return;
    if (d.role !== 'owner' || d.projects.length === 1) {
      // With nothing to switch between, the switcher is just a label — and only
      // worth showing where the page heading does not already name the project.
      var only = d.projects[0];
      var h = document.getElementById('pname');
      var named = h && h.textContent.trim() === String(only.name).trim();
      el.outerHTML = named ? '' :
        '<span class="hint" style="font-weight:600;color:var(--ink)">' +
        String(only.name).replace(/[&<>"]/g, '') + '</span>';
      return;
    }
    el.innerHTML = d.projects.map(function (p) {
      return '<option value="' + p.id + '"' + (p.id === d.current ? ' selected' : '') + '>' +
        String(p.name).replace(/[&<>"]/g, '') + (p.archived ? ' (archived)' : '') + '</option>';
    }).join('');
    el.hidden = false;
    // The switcher now carries the project's identity, so drop the duplicate heading.
    var h = document.getElementById('pname');
    if (h) h.hidden = true;
    el.addEventListener('change', async function () {
      await fetch('/api/project?p=' + encodeURIComponent(el.value), { cache: 'no-store' });
      location.reload();
    });
  } catch (e) {}
}

// Names whoever is holding this browser, beside the Sign out button. A named
// account shows the name; a shared code shows the seat and says so, because
// "Project manager (shared code)" and "Sajan" are not the same thing and the
// difference is invisible everywhere else.
var WHO_WORDS = { owner: 'Owner', manager: 'Project manager', lead: 'Discipline engineer',
                  site: 'Site team', view: 'Read-only' };
async function mountWhoAmI() {
  try {
    var bar = document.querySelector('.topbar-in');
    if (!bar || document.querySelector('.whoami')) return;
    var r = await fetch('/api/projects', { cache: 'no-store' });
    if (!r.ok) return;
    var d = await r.json();
    var span = document.createElement('span');
    var safe = function (s) { return String(s == null ? '' : s).replace(/[&<>"]/g, ''); };
    if (d.me && d.me.name) {
      span.className = 'whoami';
      span.innerHTML = 'Signed in as <b>' + safe(d.me.name) + '</b>';
      span.title = d.me.email || '';
    } else {
      span.className = 'whoami code';
      span.innerHTML = '<b>' + safe(WHO_WORDS[d.role] || d.role) + '</b> \\u00B7 shared code';
      span.title = 'This browser is holding a shared access code, not a person\\u2019s account.';
    }
    var out = bar.querySelector('a[href="/api/logout"]');
    if (out) bar.insertBefore(span, out); else bar.appendChild(span);
  } catch (e) {}
}
mountWhoAmI();`;


