export const BRAND_CSS = `
.mark { display: flex; align-items: center; flex: 0 0 auto; }
.mark img { display: block; height: 38px; width: auto; }
/* The wordmark is navy, so on a dark topbar it sits on its own white chip. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .mark img {
    background: #fff; border-radius: 6px; padding: 3px 5px; box-sizing: content-box;
  }
}
:root[data-theme="dark"] .mark img {
  background: #fff; border-radius: 6px; padding: 3px 5px; box-sizing: content-box;
}
.mark + .brand { border-left: 1px solid var(--border); padding-left: 12px; }
/* On a phone the mark wraps onto its own line, so the divider would hang in mid-air. */
@media (max-width: 560px) {
  .mark img { height: 30px; }
  .mark + .brand { border-left: none; padding-left: 0; }
}`;

